// 합성 CloudWatch(SNS) 알람 본문을 실행당 한 번만 만들고, 같은 본문의 아이템 4개(최초 1 + 재전송 3)를 낸다.
// 재전송은 SNS가 같은 알람을 다시 보내는 상황의 모사다. 서버는 계정·리전·알람 이름·상태 변경 시각으로 중복을 억제하므로
// 4번 보내도 리포트는 1개여야 한다. 중복 키는 여기서 만들지 않는다(서버의 CloudWatchAlertNormalizer 규칙).
// 입력 아이템에 AlarmName·StateChangeTime·MessageId를 주면 그 값을 쓴다(고정 입력 검증용). 없으면 현재 시각으로 만든다.
const input = $input.first().json || {};
const pad = (n, w = 2) => String(n).padStart(w, '0');
const stamp = (d) =>
  `${d.getUTCFullYear()}-${pad(d.getUTCMonth() + 1)}-${pad(d.getUTCDate())}T${pad(d.getUTCHours())}:${pad(d.getUTCMinutes())}:${pad(d.getUTCSeconds())}.${pad(d.getUTCMilliseconds(), 3)}+0000`;
const now = new Date();

const alarm = {
  AlarmName: input.AlarmName || 'n8n-example-alarm',
  AlarmDescription: input.AlarmDescription || 'n8n 예제 워크플로가 보낸 합성 알람',
  NewStateValue: 'ALARM',
  NewStateReason: input.NewStateReason || '임계값 초과(합성 예제)',
  StateChangeTime: input.StateChangeTime || stamp(now),
  Region: 'ap-northeast-2',
  AWSAccountId: '000000000000',
  Trigger: { MetricName: 'PendingThreads', Namespace: 'Custom/Hikari' },
};
const body = {
  Type: 'Notification',
  MessageId: input.MessageId || `m-${now.getTime()}`,
  Message: JSON.stringify(alarm),
};
return Array.from({ length: 4 }, () => ({ json: { ...body } }));
